def hsm(L,B=b):
    x=I(L); aa=I(20); A=1-B
    def j(t): return I('.04620')*e(-t/2)+2*e(-t)+I('7e-12')*e(-A*t)
    at=3*aa*e(10-aa)+j(aa)/aa
    return (at*x/aa*e(aa-x)+j(x)/x+I('3.04620')*e(-x/2)/(I('.4')*x)
