@lru_cache(None)
def d(l,r,B=b):
    x=I(l)
    C=cpi(l)
    if r<=58: C=minI(C,(x*x+2*x)*e(-x/2)/(8*PI)+1354*x*e(-x))
    if r<=F('43.7'): C=minI(C,e(-x/2)*(I('1.95')+I('3.9')/x+I('19.5')/x**2)+4*x*e(-x))
    if l>=58: C=minI(C,A0+117*e(-x/2)+hsm(l,B))
