        // below then it exceeds S, so its floor is 0.
        if(p<(1u<<28))pow2sum+=(U)S/(2*p*p);
        if(p<(1u<<20))pow2sum+=(U)S/(3*p*p*p);
        if(p<(1u<<15))pow2sum+=(U)S/(4*p*p*p*p);
        pow2hi+=3;
