  Z h=0; for(U k=1;k<=m;k++)h+=S/k;
  // Composite trapezoid remainder in the limit is in [0,m^-2].
  return I(h,h+m)-lnU(m)-rdiv(1,2*m)+I(0,rdiv(1,m*m).r);
