struct Sieve {
  const U N;
  std::vector<U> base;
  std::vector<uint8_t> comp;
  U low=3,hi=1;
  size_t idx=0;
  explicit Sieve(U n):N(n) {
    U m=1; while(m+1<=N/(m+1))++m;
    std::vector<uint8_t> a(m+1);
    for(U p=2;p<=m;p++)if(!a[p]){
      if(p>2)base.push_back(p);
      for(U j=p*p;j<=m;j+=p)a[j]=1;
    }
