}
I lnU(U n){return lnratio(n,1);}
I lnI(I a){
  assert(a.l>=S);
  return I(lnratio(a.l,S).l,lnratio(a.r,S).r);
}
I logp(U p){return logZ(rdiv(1,2*p-1));}
I gamma(){
  constexpr U m=1000000;
  Z h=0; for(U k=1;k<=m;k++)h+=S/k;
