      if(!(j&1))j+=p;
      for(;j<=hi;j+=2*p)comp[(j-low)/2]=1;
    }
    idx=0;return true;
  }
  U next(){
    if(hi==1){hi=1; idx=1; load(); return 2;}
    while(true){
      while(idx<comp.size()){
        size_t k=idx++;
        if(!comp[k]){U p=low+2*k;return p<=N?p:N+1;}
      }
      if(!load())return N+1;
    }
  }
};

