  if(cut>=10000000) {
    // Dusart Thm 4.2 (k=2, eta=.2) at t>=cut, with .2/L^2<.001.
    assert(lnU(cut).l>=15*S);
    eta=I(rdiv(99,100*cut).l,rdiv(101,100*cut).r);
