  constexpr U out=1000000000; // report ceiling on 10^6 times the coefficient.
  size_t k=1; std::array<U,3> worst{};

  std::array<U,31> badP={},badS={},badT={};
  I ll=lnI(rec[0].L);
  for(size_t j=1;j<rec.size();++j){
    auto x=rec[j-1],y=rec[j];
